-- PostgreSQL target schema draft; migration and RLS NOT validated.
CREATE TABLE projects (id uuid PRIMARY KEY, name text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}');
CREATE TABLE memberships (project_id uuid REFERENCES projects, principal_id text NOT NULL, role text NOT NULL CHECK(role IN ('viewer','engineer','reviewer','operator','admin')), PRIMARY KEY(project_id,principal_id));
CREATE TABLE tasks (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects, parent_id uuid REFERENCES tasks, title text NOT NULL, goal text NOT NULL, state text NOT NULL CHECK(state IN ('DRAFT','READY','RUNNING','REVIEW_REQUIRED','APPROVAL_PENDING','COMPLETED','PAUSED','FAILED','CANCELLED')), revision bigint NOT NULL DEFAULT 1, requirements jsonb NOT NULL DEFAULT '[]', constraints jsonb NOT NULL DEFAULT '{}', plan jsonb NOT NULL DEFAULT '{}', owner_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE task_dependencies (task_id uuid REFERENCES tasks, depends_on uuid REFERENCES tasks, PRIMARY KEY(task_id,depends_on), CHECK(task_id<>depends_on));
CREATE TABLE skill_versions (id text NOT NULL, version text NOT NULL, manifest jsonb NOT NULL, content_hash text NOT NULL, release_state text NOT NULL CHECK(release_state IN ('DRAFT','APPROVED','RETIRED')), reviewer_id text, PRIMARY KEY(id,version));
CREATE TABLE tool_versions (id text NOT NULL, version text NOT NULL, manifest jsonb NOT NULL, content_hash text NOT NULL, PRIMARY KEY(id,version));
CREATE TABLE tool_runs (id uuid PRIMARY KEY, task_id uuid NOT NULL REFERENCES tasks, task_revision bigint NOT NULL, skill_id text, skill_version text, tool_id text, tool_version text, idempotency_key text NOT NULL, input_hash text NOT NULL, inputs jsonb NOT NULL, status text NOT NULL CHECK(status IN ('QUEUED','SUBMITTED','WAITING','SUCCEEDED','FAILED','UNKNOWN','CANCELLED')), attempt int NOT NULL DEFAULT 1, external_job_id text, lease_owner text, lease_until timestamptz, deadline timestamptz, budget jsonb NOT NULL DEFAULT '{}', checkpoint jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(task_id,idempotency_key), FOREIGN KEY(skill_id,skill_version) REFERENCES skill_versions, FOREIGN KEY(tool_id,tool_version) REFERENCES tool_versions);
CREATE TABLE artifacts (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects, run_id uuid REFERENCES tool_runs, storage_key text NOT NULL, sha256 text NOT NULL CHECK(length(sha256)=64), mime_type text NOT NULL, byte_size bigint NOT NULL CHECK(byte_size>=0), metadata jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE hypotheses (id uuid PRIMARY KEY, task_id uuid NOT NULL REFERENCES tasks, statement text NOT NULL, mechanism_state text NOT NULL DEFAULT 'UNASSESSED' CHECK(mechanism_state IN ('UNASSESSED','PLAUSIBLE','VALIDATED','REFUTED')));
CREATE TABLE evidence (id uuid PRIMARY KEY, task_id uuid NOT NULL REFERENCES tasks, artifact_id uuid NOT NULL REFERENCES artifacts, kind text NOT NULL CHECK(kind IN ('OBSERVATION','DERIVED','SIMULATION','EXPERT_ASSESSMENT')), locator jsonb NOT NULL, conditions jsonb NOT NULL, units jsonb NOT NULL, dependency_group text NOT NULL, validity text NOT NULL CHECK(validity IN ('VALID','UNKNOWN','RETRACTED')), quality numeric NOT NULL CHECK(quality BETWEEN 0 AND 1), extraction_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE evidence_links (hypothesis_id uuid REFERENCES hypotheses, evidence_id uuid REFERENCES evidence, relation text NOT NULL CHECK(relation IN ('SUPPORTS','CONTRADICTS','NEUTRAL','UNKNOWN')), relevance numeric NOT NULL CHECK(relevance BETWEEN 0 AND 1), rationale text NOT NULL, PRIMARY KEY(hypothesis_id,evidence_id));
CREATE TABLE decisions (id uuid PRIMARY KEY, task_id uuid NOT NULL REFERENCES tasks, task_revision bigint NOT NULL, proposer_id text NOT NULL, verdict text NOT NULL CHECK(verdict IN ('PASS','FAIL','UNKNOWN')), intent text NOT NULL, snapshot jsonb NOT NULL, snapshot_hash text NOT NULL, rule_versions jsonb NOT NULL, evidence_ids jsonb NOT NULL, proposal jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE approvals (id uuid PRIMARY KEY, decision_id uuid NOT NULL REFERENCES decisions, snapshot_hash text NOT NULL, reviewer_id text NOT NULL, disposition text NOT NULL CHECK(disposition IN ('APPROVED','REJECTED','REVOKED')), reason text NOT NULL, expires_at timestamptz NOT NULL, consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rules (id text NOT NULL, version text NOT NULL, project_id uuid REFERENCES projects, content jsonb NOT NULL, scope jsonb NOT NULL, state text NOT NULL CHECK(state IN ('CANDIDATE','APPROVED','RETRACTED')), reviewer_id text, PRIMARY KEY(id,version));
CREATE TABLE retrieval_snapshots (id uuid PRIMARY KEY, task_id uuid REFERENCES tasks, task_revision bigint NOT NULL, query jsonb NOT NULL, artifact_versions jsonb NOT NULL, rule_versions jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events (id bigserial PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects, task_id uuid REFERENCES tasks, actor_id text NOT NULL, event_type text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox (id bigserial PRIMARY KEY, task_id uuid REFERENCES tasks, event_type text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz);
CREATE INDEX tasks_project_state ON tasks(project_id,state);
CREATE INDEX evidence_task ON evidence(task_id);
CREATE INDEX runs_status_lease ON tool_runs(status,lease_until);
-- Before production: enforce same-project references, DAG acyclicity,
-- immutable artifact/decision/version rows, RLS and append-only audit permissions.
-- Approval consume, revision check and run creation must share a transaction.
